import { createKernel, featureDocPath, ledgerPath, type Kernel } from './core/kernel.ts'
import { GATE_IDS, isGateId, type GateId } from './core/gates/registry.ts'
import { grantHatch, resolveFlag, type Policy } from './core/gates/policy.ts'
import { mergeConfig, noddConfigPath, parseConfig } from './core/config-core.ts'
import { joinPath } from './core/path.ts'
import { closeReport, isTestFile, testEditSignals, type TestEdit } from './core/close-report.ts'
import type { Committed } from './core/state.ts'
import { destructiveReason } from './core/destructive.ts'
import { writesOnlyUnder } from './core/scratch.ts'
import {
  BUILTIN_AGENTS,
  CC_DECLARE_SCHEMA,
  CC_FLAGS,
  CC_TASK_SCHEMA,
  ENFORCED,
  MAIN,
  PROTOCOL,
  REMINDER,
  agentReadOnly,
  bashOutcome,
  ccReason,
  continueDeclaration,
  gateOfReason,
  inScratchpad,
  landsInScratchpad,
  isForgeType,
  isNewRequest,
  normalizeCall,
  snapshot,
  stagedFs,
  type Call,
  type NoddNames,
  type Refusal,
} from './cc.ts'

const names: NoddNames = { declare: 'mcp__nodd__nodd_declare', task: 'mcp__nodd__nodd_task' }
const fs = stagedFs()
const kernels = new Map<string, Kernel>()
const agents = new Map<string, { type: string; parent: string }>()
const capabilities = new Map<string, boolean | null>()
const lastDeclared = new Map<string, Record<string, unknown>>()
let requestStartAt = ''
let lastTick = 0
let allowDestructive = false

function tick(): string {
  lastTick = Math.max(Date.now(), lastTick + 1)
  return new Date(lastTick).toISOString()
}
let testEdits: Array<Omit<TestEdit, 'seq'> & { at: string }> = []
let pendingNote: string | null = null
let lastReported = -1

let booted: Promise<void> | undefined
let home = ''
let cwd = ''
let sessionId = ''
let projectRoot = ''
let enabled = false
let hatches: Policy['hatches'] = {}
let toolsRegistered = false
let lastRefusal: Refusal | null = null
let refusals = 0
let lastExport = ''

const configPath = () => noddConfigPath(home)
const switchPath = () => joinPath(home, '.local', 'state', 'nodd', 'switch.json')

async function readSwitch($: any): Promise<boolean | undefined> {
  const raw = home ? await readText($, switchPath()) : null
  if (raw === null) return undefined
  try {
    const v = JSON.parse(raw)?.enabled
    return typeof v === 'boolean' ? v : undefined
  } catch {
    return undefined
  }
}

async function writeSwitch($: any, value: boolean) {
  await $.store.set('enabled', value).catch(() => undefined)
  if (home) await $.fs.write(switchPath(), JSON.stringify({ enabled: value, at: new Date().toISOString() }) + '\n').catch(() => undefined)
}

const statePath = () => joinPath(home, '.local', 'state', 'nodd', 'sessions', `${sessionId || 'sin-id'}.json`)
const rootDir = () => projectRoot || cwd

async function readText($: any, path: string): Promise<string | null> {
  try {
    const text = await $.fs.read(path)
    return typeof text === 'string' ? text : null
  } catch {
    return null
  }
}

function boot($: any, sessionCwd?: string): Promise<void> {
  booted ??= (async () => {
    home = (await $.env.get('HOME').catch(() => '')) || ''
    cwd = sessionCwd || (await $.session.cwd().catch(() => '')) || ''
    sessionId = (await $.session.id().catch(() => '')) || ''
    enabled = (await readSwitch($)) ?? (await $.store.get('enabled').catch(() => undefined)) === true
    const saved = await $.store.get('hatches').catch(() => undefined)
    hatches = saved && typeof saved === 'object' && !Array.isArray(saved) ? (saved as Policy['hatches']) : {}
    await restoreSession($)
  })()
  return booted
}

async function syncEnabled($: any) {
  const stored = (await readSwitch($)) ?? (await $.store.get('enabled').catch(() => enabled)) === true
  if (stored === enabled) return
  enabled = stored
  if (enabled) await registerTools($)
  refreshContext($)
  await exportState($)
}

async function resolveRoot($: any): Promise<string> {
  const repo = await $.session.repo().catch(() => null)
  if (repo && typeof repo.root === 'string' && repo.root !== '') return repo.root
  return (await $.session.cwd().catch(() => '')) || cwd
}

function configGates(): Policy['config'] {
  const text = fs.existsSync(configPath()) ? fs.readFileSync(configPath(), 'utf8') : undefined
  return parseConfig(text).config.gates
}

function loadPolicy(): Policy {
  return { config: configGates(), flags: { ...CC_FLAGS }, hatches: { ...hatches } }
}

function kernelFor(key: string): Kernel {
  const existing = kernels.get(key)
  if (existing) return existing
  const kernel = createKernel({
    fs,
    cwd: rootDir,
    now: tick,
    loadPolicy,
    isReadOnlyAgent: (name) => capabilities.get(name.toLowerCase()) ?? null,
    spendHatch: (gate) => {
      const next = { ...hatches }
      delete next[gate]
      hatches = next
    },
  })
  if (key !== MAIN) {
    const parent = kernels.get(agents.get(key)?.parent ?? MAIN)?.state.committed.declaration
    if (parent) kernel.state.committed = { ...kernel.state.committed, declaration: { ...parent, files: [...parent.files], seq: 0 } }
  }
  kernels.set(key, kernel)
  return kernel
}

async function stage($: any, paths: string[]) {
  for (const path of new Set(paths)) fs.seed(path, await readText($, path))
}

async function flush($: any): Promise<string[]> {
  const problems: string[] = []
  for (const [path, text] of fs.drain()) {
    try {
      await $.fs.write(path, text)
      const back = await readText($, path)
      if (back !== text) problems.push(`read-back mismatch on ${path}`)
    } catch (err) {
      problems.push(`${path}: ${err instanceof Error ? err.message : String(err)}`)
    }
  }
  return problems
}

function testEditTexts(call: Call, before: string | null): [string, string] | null {
  const input = call.input as any
  if (Array.isArray(input.edits)) return [input.edits.map((x: any) => String(x?.old_string ?? '')).join('\n'), input.edits.map((x: any) => String(x?.new_string ?? '')).join('\n')]
  if (typeof input.new_string === 'string') return [String(input.old_string ?? ''), input.new_string]
  if (typeof input.content === 'string') return [before ?? '', input.content]
  return null
}

function requestView(): { committed: Committed; edits: TestEdit[]; size: number } {
  const events: Array<{ at: string; write?: string; run?: Committed['commandResults'][number] }> = []
  let size = 0
  for (const kernel of kernels.values()) {
    size += kernel.state.committed.toolCalls
    for (const [path, write] of kernel.state.committed.filesWritten) if (write.at >= requestStartAt) events.push({ at: write.at, write: path })
    for (const run of kernel.state.committed.commandResults) if (run.at >= requestStartAt) events.push({ at: run.at, run })
  }
  events.sort((a, b) => (a.at < b.at ? -1 : a.at > b.at ? 1 : 0))
  const filesWritten = new Map<string, { at: string; seq: number }>()
  const commandResults: Committed['commandResults'] = []
  events.forEach((event, i) => {
    if (event.write) filesWritten.set(event.write, { at: event.at, seq: i + 1 })
    if (event.run) commandResults.push({ ...event.run, seq: i + 1 })
  })
  const seqAt = (at: string) => events.filter((event) => event.at <= at).length
  const committed: Committed = {
    seen: new Set(),
    filesRead: new Set(),
    filesWritten,
    commandResults,
    delegations: 0,
    toolCalls: events.length,
    declaration: kernels.get(MAIN)?.state.committed.declaration ?? null,
  }
  const edits = testEdits.map(({ at, ...edit }) => ({ ...edit, seq: seqAt(at) }))
  return { committed, edits, size }
}

function closingText(answer: string): string | null {
  const view = requestView()
  if (view.size === lastReported) return null
  const declaration = view.committed.declaration
  const report = closeReport({
    committed: view.committed,
    since: 0,
    slug: declaration?.slug ?? null,
    runner: declaration?.runner ?? null,
    declaredFiles: declaration?.files ?? [],
    answer,
    testEdits: view.edits,
  })
  if (!report) return null
  lastReported = view.size
  pendingNote = report.warnings.length > 0 ? `NODD, cierre del turno anterior: ${report.warnings.join(' | ')}` : null
  return [report.line, ...report.warnings.map((w) => `  ⚠ ${w}`)].join('\n')
}

function clearDeclaration() {
  const main = kernels.get(MAIN)
  if (main?.state.committed.declaration) main.state.committed = { ...main.state.committed, declaration: null }
}

function refreshContext($: any) {
  try {
    $.ui.invalidate('prompt.context')
  } catch {}
}

async function saveHatches($: any) {
  await $.store.set('hatches', hatches).catch(() => undefined)
}

async function agentOf($: any, id: string): Promise<{ type: string; parent: string } | undefined> {
  const known = agents.get(id)
  if (known) return known
  const info = ((await $.agent.list().catch(() => [])) as any[]).find((a: any) => a.id === id)
  if (!info) return undefined
  const entry = { type: String(info.type ?? ''), parent: info.parentId ?? MAIN }
  agents.set(id, entry)
  return entry
}

const FORGE_READERS = new Set(['forge:revisar', 'forge:bugs', 'forge:mejoras'])

async function insideForge($: any, e: any, key: string): Promise<boolean> {
  if ((e.tool === 'Agent' || e.tool === 'Task') && FORGE_READERS.has(String(e.subagent_type))) return true
  let id = key
  for (let depth = 0; id !== MAIN && depth < 8; depth++) {
    const info = await agentOf($, id)
    if (!info) break
    if (isForgeType(info.type) && !FORGE_READERS.has(info.type)) return true
    id = info.parent
  }
  return false
}

async function agentFiles($: any, dir: string): Promise<string[]> {
  const entries = ((await $.fs.list(dir).catch(() => [])) as any[]).filter((f: any) => String(f.name).endsWith('.md'))
  const texts: string[] = []
  for (const entry of entries) {
    const text = await readText($, joinPath(dir, String(entry.name)))
    if (text !== null) texts.push(text)
  }
  return texts
}

async function resolveCapability($: any, name: unknown) {
  if (typeof name !== 'string' || name === '') return
  const key = name.toLowerCase()
  if (key in BUILTIN_AGENTS) {
    capabilities.set(key, BUILTIN_AGENTS[key] ?? null)
    return
  }
  let found: boolean | null = null
  for (const dir of [...new Set([rootDir(), cwd])].map((d) => joinPath(d, '.claude', 'agents')).concat(joinPath(home, '.claude', 'agents'))) {
    for (const text of await agentFiles($, dir)) {
      const answer = agentReadOnly(text, name)
      if (answer !== null) {
        found = answer
        break
      }
    }
    if (found !== null) break
  }
  capabilities.set(key, found)
}

function pathsFor(kernel: Kernel, call: Call): string[] {
  const paths = [configPath()]
  const declared = kernel.state.committed.declaration?.slug
  if (declared) paths.push(featureDocPath(rootDir(), declared))
  const slug = call.input.slug
  if ((call.toolName === 'nodd_declare' || call.toolName === 'nodd_task') && typeof slug === 'string' && slug !== '') {
    paths.push(featureDocPath(rootDir(), slug), ledgerPath(rootDir(), slug))
  }
  return paths
}

async function restoreSession($: any) {
  if (!sessionId) return
  const saved = await $.store.get(`session:${sessionId}`).catch(() => undefined)
  if (!saved || typeof saved !== 'object') return
  if (typeof saved.projectRoot === 'string') projectRoot = saved.projectRoot
  if (typeof saved.requestStartAt === 'string') requestStartAt = saved.requestStartAt
  if (saved.lastDeclared && typeof saved.lastDeclared === 'object') lastDeclared.set(MAIN, saved.lastDeclared)
  if (saved.declaration && typeof saved.declaration === 'object') {
    const main = kernelFor(MAIN)
    main.state.committed = { ...main.state.committed, declaration: { ...saved.declaration, seq: 0 } }
  }
}

let lastSaved = ''

async function saveSession($: any) {
  if (!sessionId) return
  const session = {
    declaration: kernels.get(MAIN)?.state.committed.declaration ?? null,
    lastDeclared: lastDeclared.get(MAIN) ?? null,
    projectRoot,
    requestStartAt,
  }
  const text = JSON.stringify(session)
  if (text === lastSaved) return
  lastSaved = text
  await $.store.set(`session:${sessionId}`, session).catch(() => undefined)
}

async function exportState($: any) {
  await saveSession($)
  if (!home) return
  await stage($, [configPath()])
  const snap = snapshot({
    sessionId,
    enabled,
    config: configGates(),
    committed: kernels.get(MAIN)?.state.committed ?? null,
    lastRefusal,
    refusals,
    agents: [...kernels.keys()].filter((k) => k !== MAIN).length,
  })
  const text = JSON.stringify(snap, null, 2) + '\n'
  if (text === lastExport) return
  lastExport = text
  await $.fs.write(statePath(), text).catch(() => undefined)
}

async function registerTools($: any) {
  if (toolsRegistered) return
  try {
    const declare = await $.tool.register({ name: 'nodd_declare', description: CC_DECLARE_SCHEMA.description, inputSchema: CC_DECLARE_SCHEMA.parameters })
    const task = await $.tool.register({ name: 'nodd_task', description: CC_TASK_SCHEMA.description, inputSchema: CC_TASK_SCHEMA.parameters })
    if (typeof declare?.tool === 'string') names.declare = declare.tool
    if (typeof task?.tool === 'string') names.task = task.tool
    toolsRegistered = true
  } catch (err) {
    $.ui.log(`nodd: no pude registrar las tools: ${err}`, { to: 'debug' })
  }
}

function recordRefusal(reason: string, gate = gateOfReason(reason)) {
  refusals += 1
  lastRefusal = { gate, reason, at: new Date().toISOString() }
}

async function serve($: any, key: string, call: Call, id: string) {
  if (call.toolName === 'nodd_declare') {
    const continued = continueDeclaration(call.input, lastDeclared.get(key) ?? lastDeclared.get(MAIN))
    if ('problem' in continued) {
      recordRefusal(continued.problem, 'nodd_declare')
      await exportState($)
      return { deny: continued.problem }
    }
    call = { ...call, input: continued.input }
    projectRoot = await resolveRoot($)
  }
  const kernel = kernelFor(key)
  await stage($, pathsFor(kernel, call))
  kernel.onToolCall({ toolName: call.toolName, toolCallId: id, input: call.input })
  const before = JSON.stringify(hatches)
  try {
    kernel.reloadPolicy()
  } catch {}
  const reply = call.toolName === 'nodd_declare' ? kernel.declare(call.input as any) : kernel.task(call.input as any)
  if (JSON.stringify(hatches) !== before) await saveHatches($)
  const problems = await flush($)
  const final = problems.length === 0 ? reply : { ok: false, text: `${reply.text}\nnodd: ${problems.join('; ')}` }
  kernel.onToolResult({ toolName: call.toolName, toolCallId: id, input: call.input, isError: !final.ok, content: final.text })
  if (final.ok && call.toolName === 'nodd_declare') lastDeclared.set(key, call.input)
  const reason = final.ok ? '' : ccReason(final.text)
  if (!final.ok) recordRefusal(reason, /^nodd\/[a-z]+:/.test(reason) ? gateOfReason(reason) : call.toolName)
  await exportState($)
  return final.ok ? { result: final.text } : { deny: reason }
}

async function readRawConfig($: any): Promise<{ raw: Record<string, unknown> } | { problem: string }> {
  const text = await readText($, configPath())
  if (text === null || text.trim() === '') return { raw: {} }
  try {
    const raw = JSON.parse(text)
    if (raw && typeof raw === 'object' && !Array.isArray(raw)) return { raw }
    return { problem: `${configPath()} no es un objeto JSON` }
  } catch (err) {
    return { problem: `${configPath()} no es JSON válido (${err instanceof Error ? err.message : String(err)})` }
  }
}

async function setGates($: any, ids: readonly GateId[], value: boolean): Promise<string | null> {
  const read = await readRawConfig($)
  if ('problem' in read) return `nodd: no toco la config: ${read.problem}. Arreglala a mano primero.`
  const gates = { ...((read.raw.gates as Record<string, unknown> | undefined) ?? {}) }
  for (const id of ids) gates[id] = { enabled: value }
  await $.fs.write(configPath(), `${JSON.stringify(mergeConfig(read.raw, { gates }), null, 2)}\n`)
  return null
}

function gateLines(config: Policy['config']): string[] {
  const policy: Policy = { config, flags: {}, hatches: {} }
  const width = Math.max(...GATE_IDS.map((id) => id.length))
  return GATE_IDS.map((id) => {
    const { enabled: on, source } = resolveFlag(id, policy)
    const where = ENFORCED.includes(id) ? 'activo en Claude Code' : 'pendiente en Claude Code'
    return `  ${id.padEnd(width)}  ${(on ? 'on' : 'off').padEnd(3)}  ${source.padEnd(7)}  ${where}`
  })
}

async function statusText($: any): Promise<string> {
  await stage($, [configPath()])
  const declaration = kernels.get(MAIN)?.state.committed.declaration
  const pending = Object.keys(hatches)
  const lines = [
    `nodd ${enabled ? 'encendido' : 'apagado'} en Claude Code${enabled ? '' : ' (no bloquea nada)'}`,
    `declaración: ${declaration ? `${declaration.intent} · ${declaration.route} · ${declaration.slug}` : 'ninguna'}`,
    'gates (compartidos con pi en ~/.pi/nodd.json):',
    ...gateLines(configGates()),
    `overrides pendientes: ${pending.length ? pending.join(', ') : 'ninguno'}`,
    `último rechazo: ${lastRefusal ? `${lastRefusal.gate} · ${lastRefusal.reason}` : 'ninguno'}`,
  ]
  const raw = await readRawConfig($)
  if ('problem' in raw) lines.push(`ojo: ${raw.problem}; todos los gates quedan en su default hasta arreglarlo`)
  return lines.join('\n')
}

async function command($: any, args: string): Promise<string> {
  const [verb = 'status', ...rest] = args.trim().split(/\s+/).filter((w) => w !== '')
  switch (verb.toLowerCase()) {
    case 'on':
      enabled = true
      await writeSwitch($, true)
      await registerTools($)
      refreshContext($)
      await exportState($)
      return `nodd: encendido. Gates activos en Claude Code: ${ENFORCED.join(', ')}.`
    case 'off':
      enabled = false
      await writeSwitch($, false)
      refreshContext($)
      await exportState($)
      return 'nodd: apagado. No bloquea nada.'
    case 'status':
      return statusText($)
    case 'gates':
      await stage($, [configPath()])
      return ['nodd gates (gate, modo, quién decide, en Claude Code):', ...gateLines(configGates())].join('\n')
    case 'gate': {
      const [id, value] = rest
      if ((value !== 'on' && value !== 'off') || !id || (id !== 'all' && !isGateId(id))) {
        return `uso: /nodd gate <${GATE_IDS.join('|')}|all> on|off`
      }
      const ids = id === 'all' ? GATE_IDS : [id as GateId]
      const problem = await setGates($, ids, value === 'on')
      if (problem) return problem
      await exportState($)
      return `nodd: gate ${id} ${value === 'on' ? 'prendido' : 'apagado'}.`
    }
    case 'allow': {
      const [gate, ...why] = rest
      if (gate === 'destructive') {
        allowDestructive = true
        return 'nodd: override de un solo uso para un comando irreversible. Lo consume el próximo.'
      }
      if (!gate || !isGateId(gate)) return `uso: /nodd allow <gate> [motivo]. Gates: ${GATE_IDS.join(', ')}`
      if (!ENFORCED.includes(gate)) return `nodd: ${gate} todavía no se aplica en Claude Code, así que no hay nada que saltear.`
      hatches = grantHatch({ config: {}, flags: {}, hatches }, gate, why.join(' '), new Date().toISOString()).hatches
      await saveHatches($)
      await exportState($)
      return `nodd: override de un solo uso para ${gate}. Lo consume el próximo rechazo de ${gate}.`
    }
    default:
      return 'uso: /nodd [status|on|off|gates|gate <id|all> on|off|allow <gate> [motivo]]'
  }
}

export function register(on: any) {
  on('session.start', async ($: any, e: any, next: any) => {
    const r = await next(e)
    await boot($, e?.cwd)
    if (enabled) await registerTools($)
    await $.command
      .register({
        name: 'nodd',
        description: 'NODD en Claude Code: gates authorize, classify y track (apagado por defecto)',
        argumentHint: 'status | on | off | gates | gate <id|all> on|off | allow <gate> [motivo]',
        immediate: true,
      })
      .catch((err: any) => $.ui.log(`nodd: /nodd no registrado: ${err}`, { to: 'debug' }))
    await exportState($)
    return r
  })

  on('command.run', { command: 'nodd' }, async ($: any, e: any) => {
    await boot($)
    await syncEnabled($)
    return { text: (await command($, String(e.args ?? ''))).replace(/^nodd: /, '') }
  })

  on('prompt.context', async ($: any, e: any, next: any) => {
    const r = await next(e)
    await boot($)
    await syncEnabled($)
    if (!enabled) return r
    return { ...r, blocks: [...(r?.blocks ?? []), { name: 'nodd', text: PROTOCOL }] }
  })

  on('prompt.submit', async ($: any, e: any, next: any) => {
    await boot($)
    await syncEnabled($)
    if (!enabled) return next(e)
    if (!isNewRequest(e)) {
      const fromUser = ['composer', 'bridge', 'sdk'].includes(String(e?.origin?.kind))
      if (!fromUser || !pendingNote) return next(e)
      const note = pendingNote
      pendingNote = null
      return next({ ...e, context: [...(e.context ?? []), note] })
    }
    clearDeclaration()
    requestStartAt = tick()
    testEdits = []
    const note = pendingNote
    pendingNote = null
    await exportState($)
    return next({ ...e, context: [...(e.context ?? []), ...(note ? [note] : []), REMINDER] })
  })

  on('turn.complete', async ($: any, e: any, next: any) => {
    const r = await next(e)
    if (!enabled || e?.agentId || e?.isAborted) return r
    const text = closingText(String(e?.answer ?? ''))
    return text ? { ...r, text } : r
  })

  on('agent.spawn', async ($: any, e: any, next: any) => {
    const r = await next(e)
    if (r?.agentId) agents.set(r.agentId, { type: String(e.subagentType ?? ''), parent: e.parentAgentId ?? MAIN })
    return r
  })

  on('tool.call', async ($: any, e: any, next: any) => {
    await boot($)
    await syncEnabled($)
    const isNodd = e.tool === names.declare || e.tool === names.task
    if (!enabled && !isNodd) return next(e)
    const key: string = e.agentId ?? MAIN
    const id = String(e.tool_use_id ?? `nodd-${Date.now()}`)
    const call = normalizeCall(String(e.tool), e, names)
    if (isNodd) return serve($, key, call, id)
    const lands = (path: unknown) => landsInScratchpad((p) => $.fs.stat(p, { resolve: true }), path, sessionId)
    if ((call.toolName === 'write' || call.toolName === 'edit') && await lands(call.input.file_path ?? call.input.path)) return next(e)
    if (call.toolName === 'bash') {
      const harm = destructiveReason(String(call.input.command ?? ''), [rootDir(), '/tmp'], home, cwd)
      if (harm && allowDestructive) allowDestructive = false
      else if (harm) {
        const reason = `nodd/destructive: ${harm}, and NODD never runs that on the model's behalf, not even inside forge. To proceed: use the safer command named above if there is one, or, if the user wants exactly this, ask them to run it themselves with \`! ${String(call.input.command ?? '').split('\n')[0]}\`, or to allow it once with /nodd allow destructive`
        recordRefusal(reason, 'destructive')
        await exportState($)
        return { deny: reason }
      }
    }
    if (call.toolName === 'bash') {
      const targets: string[] = []
      const only = writesOnlyUnder(String(call.input.command ?? ''), (path) => inScratchpad(path, sessionId), (path) => targets.push(path))
      if (only && (await Promise.all(targets.map(lands))).every(Boolean)) return next(e)
    }
    const forge = await insideForge($, e, key)
    const kernel = kernelFor(key)

    let decision: { block: true; reason: string } | null = null
    if (!forge) {
      await stage($, pathsFor(kernel, call))
      if (call.toolName === 'subagent') await resolveCapability($, call.input.agent)
      const before = JSON.stringify(hatches)
      try {
        kernel.reloadPolicy()
        decision = kernel.checkCall(call)
      } catch (err) {
        decision = { block: true, reason: `nodd/internal: a gate failed (${err instanceof Error ? err.message : String(err)}), so NODD refuses the call instead of letting it through unchecked. To proceed: ask the user to turn NODD off with /nodd off and report the error` }
      }
      if (JSON.stringify(hatches) !== before) await saveHatches($)
      await flush($)
    }
    kernel.onToolCall({ toolName: call.toolName, toolCallId: id, input: call.input })
    if (decision) {
      kernel.forgetPending(id)
      const reason = ccReason(decision.reason)
      recordRefusal(reason)
      await exportState($)
      return { deny: reason }
    }

    const path = call.input.file_path ?? call.input.path
    const testPath = (call.toolName === 'write' || call.toolName === 'edit') && typeof path === 'string' && isTestFile(path) ? path : null
    const prior = testPath && typeof call.input.content === 'string' ? await readText($, testPath) : null
    let r: any
    try {
      r = await next(e)
    } catch (err) {
      kernel.forgetPending(id)
      throw err
    }
    if (r && typeof r.deny === 'string') kernel.forgetPending(id)
    else {
      const seen = call.toolName === 'bash' ? bashOutcome(r) : { isError: r?.isError === true, content: String(r?.text ?? '') }
      kernel.onToolResult({ toolName: call.toolName, toolCallId: id, input: call.input, ...seen })
      const texts = testPath && !seen.isError ? testEditTexts(call, prior) : null
      if (texts) testEdits.push({ path: testPath!, at: kernel.state.committed.filesWritten.get(testPath!)?.at ?? new Date().toISOString(), ...testEditSignals(texts[0], texts[1]) })
    }
    await exportState($)
    return r
  })
}

